1	//! `SortedMap`: an ordered key/value map with the shape of the C++ original.
2	//!
3	//! | C++                        | Rust                                |
4	//! |----------------------------|-------------------------------------|
5	//! | `m.insert(k, v)`           | [`insert`](SortedMap::insert)       |
6	//! | `m[k]`                     | [`entry_or_default`](SortedMap::entry_or_default) |
7	//! | `m.contains(k)`            | [`contains_key`](SortedMap::contains_key) |
8	//! | `m.get(k, fallback)`       | [`get_or`](SortedMap::get_or)       |
9	//! | `m.erase(k)`               | [`remove`](SortedMap::remove)       |
10	//! | `m.size()` / `m.empty()`   | [`len`](SortedMap::len) / [`is_empty`](SortedMap::is_empty) |
11	//! | `m.find(k)` / `m.end()`    | [`find`](SortedMap::find) / [`end`](SortedMap::end) |
12	//! | `m.lower_bound(k)`         | [`lower_bound`](SortedMap::lower_bound) |
13	//! | `m.upper_bound(k)`         | [`upper_bound`](SortedMap::upper_bound) |
14	//! | `m.equal_range(k)`         | [`equal_range`](SortedMap::equal_range) |
15	
16	use super::buckets::{Buckets, DEFAULT_LOAD_FACTOR};
17	use super::cursor::Cursor;
18	
19	pub struct SortedMap<K, V> {
20	    store: Buckets<K, V>,
21	}
22	
23	impl<K: Ord, V> SortedMap<K, V> {
24	    pub fn new() -> Self {
25	        SortedMap::with_load_factor(DEFAULT_LOAD_FACTOR)
26	    }
27	
28	    /// Same map, with the bucket size tuned. Only the constant factors change.
29	    pub fn with_load_factor(load: usize) -> Self {
30	        SortedMap {
31	            store: Buckets::new(load),
32	        }
33	    }
34	
35	    /// Number of entries. Mirrors `size()`.
36	    pub fn len(&self) -> usize {
37	        self.store.len()
38	    }
39	
40	    /// Mirrors `empty()`.
41	    pub fn is_empty(&self) -> bool {
42	        self.store.is_empty()
43	    }
44	
45	    pub fn clear(&mut self) {
46	        self.store.clear();
47	    }
48	
49	    /// Stores `value` under `key`, returning the value it displaced, if any.
50	    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
51	        self.store.insert(key, value)
52	    }
53	
54	    pub fn contains_key(&self, key: &K) -> bool {
55	        self.store.get(key).is_some()
56	    }
57	
58	    pub fn get(&self, key: &K) -> Option<&V> {
59	        self.store.get(key)
60	    }
61	
62	    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
63	        self.store.get_mut(key)
64	    }
65	
66	    /// The value under `key`, or `fallback` when the key is absent. Mirrors the
67	    /// two-argument `get(key, fallback)`, which — unlike `operator[]` — inserts nothing.
68	    pub fn get_or<'a>(&'a self, key: &K, fallback: &'a V) -> &'a V {
69	        self.store.get(key).unwrap_or(fallback)
70	    }
71	
72	    /// Removes `key`, returning its value when it was present. Mirrors `erase(key)`.
73	    pub fn remove(&mut self, key: &K) -> Option<V> {
74	        self.store.remove(key)
75	    }
76	
77	    /// Entries in ascending key order.
78	    pub fn iter<'a>(&'a self) -> impl Iterator<Item = (&'a K, &'a V)> + 'a {
79	        self.store.iter()
80	    }
81	
82	    /// Keys in ascending order. Mirrors `keys()`.
83	    pub fn keys(&self) -> Vec<K>
84	    where
85	        K: Clone,
86	    {
87	        self.store.iter().map(|(key, _)| key.clone()).collect()
88	    }
89	
90	    /// Values ordered by their keys. Mirrors `values()`.
91	    pub fn values(&self) -> Vec<V>
92	    where
93	        V: Clone,
94	    {
95	        self.store.iter().map(|(_, value)| value.clone()).collect()
96	    }
97	
98	    /// Cursor on `key`, or the end cursor when it is absent.
99	    pub fn find(&self, key: &K) -> Cursor<K, V> {
100	        Cursor::new(&self.store, self.store.find(key))
101	    }
102	
103	    /// Cursor on the first entry whose key is `>= key`.
104	    pub fn lower_bound(&self, key: &K) -> Cursor<K, V> {
105	        Cursor::new(&self.store, self.store.lower_bound(key))
106	    }
107	
108	    /// Cursor on the first entry whose key is `> key`.
109	    pub fn upper_bound(&self, key: &K) -> Cursor<K, V> {
110	        Cursor::new(&self.store, self.store.upper_bound(key))
111	    }
112	
113	    /// The half-open cursor range covering `key`. Keys are unique, so it spans at most
114	    /// one entry — it is empty exactly when `key` is absent.
115	    pub fn equal_range(&self, key: &K) -> (Cursor<K, V>, Cursor<K, V>) {
116	        (self.lower_bound(key), self.upper_bound(key))
117	    }
118	
119	    /// The past-the-end cursor. Mirrors `end()`.
120	    pub fn end(&self) -> Cursor<K, V> {
121	        Cursor::new(&self.store, self.store.end())
122	    }
123	}
124	
125	impl<K: Ord, V: Default> SortedMap<K, V> {
126	    /// The value under `key`, inserting a default-constructed one first when the key is
127	    /// absent. This is C++ `operator[]` on a non-const map: merely reading a missing key
128	    /// through it grows the map, which the original program relies on.
129	    pub fn entry_or_default(&mut self, key: K) -> &mut V {
130	        self.store.get_or_insert_with(key, V::default)
131	    }
132	}
133	
134	impl<K: Ord, V> Default for SortedMap<K, V> {
135	    fn default() -> Self {
136	        SortedMap::new()
137	    }
138	}
139	
140	#[cfg(test)]
141	mod tests {
142	    use super::*;
143	
144	    #[test]
145	    fn indexing_a_missing_key_inserts_a_default() {
146	        let mut map: SortedMap<(i32, i32), String> = SortedMap::new();
147	        assert_eq!(map.entry_or_default((3, 6)), "");
148	        assert_eq!(map.len(), 1);
149	        assert!(map.contains_key(&(3, 6)));
150	
151	        *map.entry_or_default((3, 6)) = String::from("modified");
152	        assert_eq!(map.entry_or_default((3, 6)), "modified");
153	        assert_eq!(map.len(), 1);
154	    }
155	
156	    #[test]
157	    fn get_or_does_not_insert() {
158	        let mut map: SortedMap<i32, String> = SortedMap::new();
159	        map.insert(1, String::from("one"));
160	        let fallback = String::from("default");
161	        assert_eq!(map.get_or(&1, &fallback), "one");
162	        assert_eq!(map.get_or(&2, &fallback), "default");
163	        assert_eq!(map.len(), 1);
164	    }
165	
166	    #[test]
167	    fn keys_and_values_come_back_sorted_and_aligned() {
168	        let mut map: SortedMap<(i32, i32), String> = SortedMap::with_load_factor(2);
169	        for key in [3, 1, 4, 1, 5, 9, 2, 6] {
170	            map.insert((key, key * 2), format!("value_{}", key));
171	        }
172	        let keys = map.keys();
173	        let values = map.values();
174	        assert_eq!(keys, vec![(1, 2), (2, 4), (3, 6), (4, 8), (5, 10), (6, 12), (9, 18)]);
175	        assert_eq!(values.len(), keys.len());
176	        for (key, value) in keys.iter().zip(values.iter()) {
177	            assert_eq!(value, &format!("value_{}", key.0));
178	        }
179	    }
180	
181	    #[test]
182	    fn tuple_keys_order_lexicographically_like_std_tuple() {
183	        let mut map: SortedMap<(i32, i32), i32> = SortedMap::with_load_factor(2);
184	        for key in [(1, 9), (0, 5), (1, 2), (-1, 0), (0, 4)] {
185	            map.insert(key, 0);
186	        }
187	        assert_eq!(map.keys(), vec![(-1, 0), (0, 4), (0, 5), (1, 2), (1, 9)]);
188	    }
189	
190	    #[test]
191	    fn cursors_behave_like_map_iterators() {
192	        let mut map: SortedMap<(i32, i32), String> = SortedMap::with_load_factor(2);
193	        for key in 0..10 {
194	            map.insert((key, key * 2), format!("value_{}", key));
195	        }
196	
197	        assert!(map.find(&(6, 12)) != map.end());
198	        assert_eq!(map.find(&(6, 12)).value().map(String::as_str), Some("value_6"));
199	        assert!(map.find(&(6, 13)) == map.end());
200	        assert_eq!(map.find(&(6, 13)).value(), None);
201	        assert!(map.end().is_end());
202	
203	        assert_eq!(map.lower_bound(&(7, 14)).key(), Some(&(7, 14)));
204	        assert_eq!(map.upper_bound(&(7, 14)).key(), Some(&(8, 16)));
205	        // A key that is absent: both bounds land on the following entry.
206	        assert_eq!(map.lower_bound(&(7, 0)).key(), Some(&(7, 14)));
207	        assert_eq!(map.upper_bound(&(7, 0)).key(), Some(&(7, 14)));
208	        // Past the last key: both bounds are the end.
209	        assert!(map.lower_bound(&(10, 0)) == map.end());
210	        assert!(map.upper_bound(&(9, 18)) == map.end());
211	
212	        // Walking the whole map with a cursor visits everything in order.
213	        let mut cursor = map.lower_bound(&(i32::MIN, i32::MIN));
214	        let mut walked = Vec::new();
215	        while cursor != map.end() {
216	            walked.push(*cursor.key().unwrap());
217	            cursor.advance();
218	        }
219	        assert_eq!(walked, map.keys());
220	    }
221	
222	    #[test]
223	    fn equal_range_spans_one_entry_when_present_and_none_otherwise() {
224	        let mut map: SortedMap<(i32, i32), i32> = SortedMap::with_load_factor(2);
225	        for key in 0..10 {
226	            map.insert((key, key * 2), key);
227	        }
228	        for (probe, expected) in [((8, 16), 1), ((8, 17), 0), ((99, 0), 0)] {
229	            let (first, last) = map.equal_range(&probe);
230	            let mut cursor = first;
231	            let mut count = 0;
232	            while cursor != last {
233	                count += 1;
234	                cursor.advance();
235	            }
236	            assert_eq!(count, expected, "probe {:?}", probe);
237	        }
238	    }
239	
240	    #[test]
241	    fn clear_resets_everything_including_cursors() {
242	        let mut map: SortedMap<i32, i32> = SortedMap::with_load_factor(2);
243	        for key in 0..50 {
244	            map.insert(key, key);
245	        }
246	        map.clear();
247	        assert_eq!(map.len(), 0);
248	        assert!(map.is_empty());
249	        assert!(map.find(&0) == map.end());
250	        assert!(map.lower_bound(&0) == map.end());
251	        assert!(map.keys().is_empty());
252	    }
253	
254	    #[test]
255	    fn matches_btreemap_under_random_operations() {
256	        use std::collections::BTreeMap;
257	
258	        let mut state = 0x9E37_79B9_7F4A_7C15u64;
259	        let mut next = move || {
260	            state ^= state << 13;
261	            state ^= state >> 7;
262	            state ^= state << 17;
263	            state
264	        };
265	        let mut map: SortedMap<i32, i32> = SortedMap::with_load_factor(3);
266	        let mut model: BTreeMap<i32, i32> = BTreeMap::new();
267	        for step in 0..5000 {
268	            let key = (next() % 200) as i32;
269	            match next() % 4 {
270	                0 => assert_eq!(map.remove(&key), model.remove(&key)),
271	                1 => assert_eq!(map.insert(key, step), model.insert(key, step)),
272	                2 => assert_eq!(*map.entry_or_default(key), *model.entry(key).or_default()),
273	                _ => assert_eq!(map.get(&key), model.get(&key)),
274	            }
275	            assert_eq!(map.len(), model.len());
276	        }
277	        assert_eq!(map.keys(), model.keys().copied().collect::<Vec<_>>());
278	        assert_eq!(map.values(), model.values().copied().collect::<Vec<_>>());
279	        for probe in -2..205 {
280	            assert_eq!(map.lower_bound(&probe).key(), model.range(probe..).next().map(|(k, _)| k));
281	            assert_eq!(
282	                map.upper_bound(&probe).key(),
283	                model.range(probe + 1..).next().map(|(k, _)| k)
284	            );
285	            assert_eq!(map.contains_key(&probe), model.contains_key(&probe));
286	        }
287	    }
288	}
